(function(root){
'use strict';
const a=root.VersionCompassExactReleases,esc=a.esc;
function data(){return root.SPLUNK_DATA.guidance;}
function refs(ids){return ids.map(id=>'<a href="'+esc(data().sources[id].url)+'" target="_blank" rel="noopener noreferrer">'+esc(data().sources[id].title)+'</a>').join(' · ');}
function evidence(row){return '<p>'+esc(row.explanation)+'</p>'+(row.claims.length?row.claims.map(c=>'<div class="exact-evidence"><p><strong>'+esc(c.state)+'</strong> — '+esc(c.text)+'</p><p>'+esc(c.qualification)+'</p><p>Claim '+esc(c.id)+' · Assessed '+esc(c.assessment.date)+' · Verification basis '+esc(c.assessment.verificationDate)+' · '+esc(c.assessment.status)+'</p><p>Scope: '+esc(c.scope.product)+' / '+esc(c.scope.component)+' / '+esc(c.scope.branch)+' / '+esc(c.scope.versions?.join(', ')||c.scope.from+' through '+c.scope.through)+'</p><p>Section: '+esc(c.assessment.section)+' · '+refs(c.assessment.src)+'</p></div>').join(''):'<p>Evidence needed: an assessed public claim for this component, branch and release.</p>');}
function cards(r,print=false){return r.rows.map(row=>'<article class="exact-card"><h3>'+esc(row.title)+'</h3><p class="exact-states"><span>From '+esc(r.from.release.version)+'<strong>'+esc(row.from.status)+'</strong><small>'+esc(row.from.freshness)+'</small></span><span>Target '+esc(r.to.release.version)+'<strong>'+esc(row.to.status)+'</strong><small>'+esc(row.to.freshness)+'</small></span></p><p>'+esc(row.net)+'. A matching state does not prove identical software or complete evidence.</p>'+(print?'<h4>Why the source state applies</h4>'+evidence(row.from)+'<h4>Why the target state applies</h4>'+evidence(row.to):'<details><summary>Why these findings apply</summary><h4>Source release</h4>'+evidence(row.from)+'<h4>Target release</h4>'+evidence(row.to)+'</details>')+'</article>').join('');}
function event(e){const g=data().exactReleases,r=g.releases.find(r=>r.id===e.release);return '<li><strong>'+esc(r.version)+' / '+esc(r.component)+' · '+esc(e.type)+'</strong><p>'+e.claims.map(id=>{const c=g.claims.find(c=>c.id===id);return esc(c.text)+' '+refs(c.assessments.at(-1).src);}).join('</p><p>')+'</p>'+(e.type==='backport'?'<p>Older-branch fix for the same CVE; parallel remediation does not establish code ancestry or release-date order.</p>':'')+(e.detail?'<p>'+esc(e.detail)+'</p>':'')+'</li>';}
function timeline(r){return '<p>The following catalog events fall within the selected version interval. Branch version order is separate from publication dates. These entries are not installed hops.</p><ol class="exact-timeline">'+(r.intervalEvents.length?r.intervalEvents.map(event).join(''):'<li>No catalog event recorded in this interval. This is not proof of no software changes.</li>')+'</ol>';}
function directory(){return '<ul class="exact-directory">'+Object.entries(data().sources).filter(([id])=>id.startsWith('exact')).map(([id,s])=>'<li><strong>'+esc(s.title)+'</strong><p>'+refs([id])+'</p><p>Assessed section: '+esc(s.section)+' · Source checked '+esc(s.checked)+' · Scope assessed '+esc(s.reviewed)+'</p></li>').join('')+'</ul>';}
function corrections(asOf){const g=data().exactReleases;const rows=g.events.filter(e=>e.type==='documentation-correction'&&e.claims.some(id=>g.claims.find(c=>c.id===id).assessments.some(a=>a.date<=asOf&&a.status==='supported')));return rows.length?rows.map(event).join(''):'<li>No documentation-correction assessment is recorded by the selected evidence date.</li>';}
function report(r){const html='<header class="report-title"><p>VERSION COMPASS / EXACT RELEASE PILOT</p><h1>Exact release comparison</h1><p>'+esc(r.from.release.component)+' · '+esc(r.from.release.version)+' to '+esc(r.to.release.version)+' · Evidence as of '+esc(r.to.asOf)+'</p></header><p>'+esc(r.boundary)+'</p><section class="report-section"><h2>Net differences at target</h2>'+cards(r,true)+'</section><section class="report-section"><h2>Release timeline</h2>'+timeline(r)+'</section><section class="report-section"><h2>Changes encountered on an upgrade route</h2><p>'+esc(r.path.reason)+'</p><p>Supported exact upgrade route: '+esc(r.path.status)+'. No route changes are asserted when the route is unknown.</p></section><section class="report-section"><h2>Documentation corrections</h2><p>Documentation-only events remain separate from software changes and retain their assessment dates.</p><ul>'+corrections(r.to.asOf)+'</ul><p>A documentation update does not create another software change or renew an assessment.</p></section><section class="report-section"><h2>Sources and bounded coverage</h2><p>These public sections define this assessed pilot. Dates apply only to the named claim scopes.</p>'+directory()+'<p>No customer context is collected. Existing release-line guidance remains independently available.</p></section>';
 return '<article class="edition-report exact-report">'+(root.VersionCompassReports?.decorate(html,Object.entries(data().sources).filter(([id])=>id.startsWith('exact')).map(([,s])=>s.url))||html)+'</article>';}
const api={cards,evidence,timeline,directory,corrections,report};root.VersionCompassExactView=api;
if(typeof module==='object'&&module.exports)module.exports=api;
}(typeof window==='object'?window:globalThis));
